    13  #define FUZZ_BEGIN_DATA(data_arg, size_arg) \
    14          int LLVMFuzzerTestOneInput(data_arg, size_arg); \
    15          int LLVMFuzzerTestOneInput(data_arg, size_arg) { \
    16                  struct fuzzer_context fuzz_ctx; \
    17                  fuzzer_init(&fuzz_ctx); T_BEGIN {
    18
    19  #define FUZZ_BEGIN_STR(str_arg) \
    20          FUZZ_BEGIN_DATA(const uint8_t *_param_data, size_t _param_size) \
    21          str_arg = t_strndup(_param_data, _param_size);
