    24          FUZZ_BEGIN_DATA(const uint8_t *_param_data, size_t _param_size) \
    25          fuzz_ctx.ioloop = io_loop_create(); \
    26          (void)fuzzer_io_as_fd(&fuzz_ctx, _param_data, _param_size);
    27
