    14  void fuzzer_init(struct fuzzer_context *fuzz_ctx)
    15  {
    16          i_zero(fuzz_ctx);
    17          if (!lib_is_initialized()) {
    18                  lib_init();
    19                  lib_signals_init();
    20                  lib_signals_ignore(SIGPIPE, TRUE);
    21          }
    22          fuzz_ctx->fd = -1;
    23  }
    24
    25  void fuzzer_deinit(struct fuzzer_context *fuzz_ctx)
    26  {
    27          iostream_pump_destroy(&fuzz_ctx->pump);
    28          /* ensure fd gets closed, we don't care
    29             if this fails. */
    30          if (fuzz_ctx->fd > -1)
    31                  (void)close(fuzz_ctx->fd);
    32          if (fuzz_ctx->fd_pump > -1)
    33                  (void)close(fuzz_ctx->fd_pump);
    34          if (fuzz_ctx->ioloop != NULL)
    35                  io_loop_destroy(&fuzz_ctx->ioloop);
    36  }
    37
    38  static void pump_finished(enum iostream_pump_status status ATTR_UNUSED,
    39                            struct fuzzer_context *fuzz_ctx)
    40  {
    41          struct istream *input = iostream_pump_get_input(fuzz_ctx->pump);
    42          struct ostream *output = iostream_pump_get_output(fuzz_ctx->pump);
    43
    44          switch (status) {
    45          case IOSTREAM_PUMP_STATUS_INPUT_EOF:
    46                  break;
    47          case IOSTREAM_PUMP_STATUS_INPUT_ERROR:
    48                  i_error("read(%s) failed: %s", i_stream_get_name(input),
    49                          i_stream_get_error(input));
    50                  break;
    51          case IOSTREAM_PUMP_STATUS_OUTPUT_ERROR:
    52                  i_error("write(%s) failed: %s", o_stream_get_name(output),
    53                          o_stream_get_error(output));
    54                  break;
    55          };
    56
    57          if (shutdown(o_stream_get_fd(output), SHUT_WR) < 0)
    58                  i_fatal("shutdown() failed: %m");
    59          iostream_pump_destroy(&fuzz_ctx->pump);
    60  }
    61
    62  int fuzzer_io_as_fd(struct fuzzer_context *fuzz_ctx,
    63                     const uint8_t *data, size_t size)
    64  {
    65          int sfd[2];
    66
    67          if (socketpair(AF_UNIX, SOCK_STREAM, 0, sfd) < 0)
    68                  i_fatal("socketpair() failed: %m");
    69          net_set_nonblock(sfd[0], TRUE);
    70          net_set_nonblock(sfd[1], TRUE);
    71
    72          struct istream *input = i_stream_create_from_data(data, size);
    73          struct ostream *output = o_stream_create_fd(sfd[0], IO_BLOCK_SIZE);
    74          fuzz_ctx->pump = iostream_pump_create(input, output);
    75          fuzz_ctx->fd_pump = sfd[0];
    76          fuzz_ctx->fd = sfd[1];
    77          iostream_pump_set_completion_callback(fuzz_ctx->pump, pump_finished,
    78                                                fuzz_ctx);
    79          i_stream_unref(&input);
    80          o_stream_unref(&output);
    81          iostream_pump_start(fuzz_ctx->pump);
    82          return sfd[1];
    83  }
